from lesson_helpers import *
titles=['Définition','Épidémiologie','Physiopathologie','Démarche clinique','Anamnèse','Examen clinique','Syndromes','Diagnostic positif','Explorations','Arbre diagnostique et diagnostics différentiels','Prise en charge','Prévention, suivi et pronostic','Points clés','Pièges']
a='''<template id="ch-N00"><div class="chap"><div class="chap-head"><div class="code">N00 · N-07-Néphrologie</div><h1>Syndrome néphritique aigu</h1><span class="status">Monographie pédagogique · Auto-relecture IA documentée · Sans validation médicale humaine</span></div><div class="tabs ui" role="tablist"><button role="tab" aria-controls="pA" data-p="pA" aria-selected="true">⚕ Pathologie et prise en charge</button><button role="tab" aria-controls="pE" data-p="pE" aria-selected="false">🔬 Examens complémentaires</button><button role="tab" aria-controls="pS" data-p="pS" aria-selected="false">⚛ Sciences fondamentales spécialisées</button><button role="tab" aria-controls="pP" data-p="pP" aria-selected="false">💊 Pharmacologie</button></div><div class="panel" id="pA"><nav class="toc ui"><b>Plan monographique</b><ol>'''+''.join('<li><a href="#n00-'+str(i)+'">'+t+'</a></li>' for i,t in enumerate(titles,1))+'''</ol></nav><div class="chap-body" data-semiology-clinical="N00">'''
a+=sec('question','Une urine sombre, mais quelle urgence ?', '''<p><b>Vignette pédagogique fictive.</b> Une personne de 32 ans consulte pour des urines brunâtres, des paupières gonflées et une baisse des urines depuis trois jours. Une infection pharyngée a précédé ces symptômes d’environ deux semaines. La pression artérielle est de 174/104 mmHg ; la créatinine est passée de 75 à 150 µmol/L en cinq jours. La première question n’est pas le nom du germe : il faut rechercher une dyspnée, une atteinte neurologique, une hyperkaliémie et l’évolution de la diurèse, puis confirmer l’origine glomérulaire de l’hématurie.</p><p>Ce tableau suggère un syndrome néphritique aigu. Le contexte rend une cause postinfectieuse plausible, mais ne la prouve pas. Une infection active, une maladie auto-immune ou une autre cause glomérulaire restent possibles. Les valeurs de la vignette sont construites pour l’apprentissage ; elles ne décrivent pas un patient réel.</p>'''+key('Reconnaître le syndrome déclenche une conduite ; identifier la cause détermine le traitement.'),('CH-URGENCE','EU-SYNDROMES'))
a+=sec(1,'1. Définition', '''<p>Le <b>syndrome néphritique aigu</b> est une présentation clinique d’atteinte glomérulaire inflammatoire apparue en quelques jours. Son noyau associe une hématurie d’origine glomérulaire et une protéinurie, avec une baisse variable de la filtration. La rétention de sodium et d’eau explique l’œdème, l’hypertension artérielle et souvent l’oligurie. L’intensité de ces manifestations varie : une hématurie microscopique peut accompagner une atteinte rénale sévère, et l’absence d’œdème visible n’exclut pas le syndrome.</p><p>Il s’agit d’un <b>syndrome, pas d’un diagnostic étiologique</b>. Le terme ne signifie pas automatiquement « infection à streptocoque », « croissants » ou « maladie auto-immune ». La glomérulonéphrite décrit la lésion inflammatoire ; son type doit être établi par le contexte, la biologie et, lorsqu’elle est indiquée, la biopsie. La '''+w('nephritique-nephrotique','distinction entre néphritique et néphrotique')+''' évite de déduire la maladie de la seule présence d’œdèmes.</p><p>Une détérioration rénale rapide en quelques jours ou semaines fait craindre une glomérulonéphrite rapidement progressive. Cette présentation peut se superposer au syndrome néphritique ; elle rend l’évaluation urgente. Le code N00 sert au classement de la présentation aiguë. Les suffixes morphologiques figurent en annexe, après le raisonnement clinique.</p>'''+key('Hématurie glomérulaire + protéinurie + retentissement rénal ou hydrosodé : penser au syndrome néphritique et mesurer sa dynamique.'),('EU-SYNDROMES','CH-URGENCE','CH-CIM'))
a+=sec(2,'2. Épidémiologie : préciser la population', '''<p>La fréquence d’un syndrome dépend de sa définition et du recrutement : patients de premier recours, enfants hospitalisés et adultes biopsiés ne constituent pas le même dénominateur. Les sources suisses consultées ne fournissent pas une incidence nationale récente de l’ensemble des syndromes néphritiques aigus. Aucun chiffre de glomérulonéphrite rapidement progressive ni de microhématurie n’est donc présenté ici comme l’incidence de N00.</p><p>Le CUEN décrit une diminution de l’incidence de la forme postinfectieuse typique. KDIGO rappelle cependant que les infections liées aux glomérulonéphrites sont diverses : chez l’adulte, l’infection peut encore être active, notamment dans une endocardite ou une infection staphylococcique sur terrain comorbide. La forme poststreptococcique de l’enfant et la forme associée à une infection active chez l’adulte n’ont ni le même contexte ni le même pronostic.</p><p>La néphropathie à IgA est une autre cause importante d’hématurie glomérulaire, notamment récidivante chez l’adulte jeune. Son importance dans les biopsies n’autorise pas à lui attribuer une proportion fixe de tous les tableaux néphritiques aigus. En pratique, l’âge, les antécédents rénaux, le diabète, les infections récentes ou persistantes et les signes systémiques modifient les hypothèses avant les tests.</p>'''+key('Une fréquence sans population ni dénominateur aide peu à décider ; l’absence de donnée suisse directe reste explicite.'),('EU-SYNDROMES','EU-IGA','INT-INFECTION'))
a+=sec(3,'3. Physiopathologie : du filtre lésé au tableau clinique', '''<p>Le filtre glomérulaire normal sépare le sang de l’espace urinaire grâce à l’endothélium, à la membrane basale et aux podocytes. L’eau et les petits solutés traversent cette barrière, tandis que les cellules sanguines sont retenues. Une lésion inflammatoire rend possible le passage d’hématies et augmente le passage de protéines. Les hématies peuvent se déformer au cours de ce passage ; dans le tubule, elles peuvent être incorporées dans un moulage protéique, formant un '''+w('sediment','cylindre érythrocytaire')+'''.</p><p>La prolifération endocapillaire et l’infiltration inflammatoire gênent la filtration. Lorsque le rein élimine moins de sodium et d’eau que l’organisme n’en reçoit, le volume extracellulaire augmente : prise de poids, œdèmes et hypertension apparaissent. L’œdème néphritique n’exige donc pas une hypoalbuminémie profonde. Une expansion importante peut se traduire par une congestion pulmonaire. Le degré de protéinurie et l’albuminémie permettent de reconnaître une composante néphrotique associée.</p><p>Si les capillaires sont fortement lésés, une prolifération peut occuper l’espace de Bowman : c’est le '''+w('croissant','croissant extracapillaire')+'''. Les lésions actives et les cicatrices fibreuses n’ont pas la même signification pronostique. La rapidité de la perte de fonction justifie d’agir avant que la lésion ne devienne irréversible.</p>'''+table(['Mécanisme dominant','Expression clinique ou biologique','Conséquence pratique'],[
['Lésion du filtre','Hématies dysmorphiques, cylindres, protéinurie','Analyser le sédiment et quantifier la protéinurie.'],
['Filtration réduite et rétention hydrosodée','Créatinine ascendante, oligurie, poids et pression augmentés','Suivre les tendances et rechercher une surcharge pulmonaire.'],
['Activation immunologique','Complément consommé dans certaines causes ; auto-anticorps dans d’autres','Interpréter les tests avec la clinique, sans sérologie universelle.'],
['Lésion extracapillaire sévère','Perte rapide de fonction, parfois syndrome réno-pulmonaire','Organiser une évaluation néphrologique et histologique urgente.']])+'''<p>Les mécanismes ne sont pas interchangeables. Complexes immuns, anticorps anti-membrane basale et vascularite pauci-immune peuvent aboutir à un tableau proche tout en appelant des traitements différents. Les six disciplines de l’onglet Sciences développent ces liens et les limites de leur lecture.</p>''',('EU-HISTO','CH-SEDIMENT','CH-URGENCE','INT-INFECTION','EU-IRA'))
a+=sec(4,'4. Démarche clinique : gravité, localisation, cause', '''<p><b>Première étape : sécuriser.</b> Rechercher d’emblée détresse respiratoire, signes neurologiques, douleur thoracique, anurie ou baisse marquée des urines. Mesurer pression, saturation, fréquence respiratoire et état circulatoire ; obtenir rapidement créatinine, potassium et évaluation acido-basique selon gravité. Une atteinte menaçante justifie une prise en charge hospitalière immédiate et l’avis néphrologique, sans attendre le résultat de tous les anticorps.</p><p><b>Deuxième étape : localiser.</b> La bandelette dépiste, le sédiment confirme les hématies et recherche leur morphologie ainsi que les cylindres. Quantifier la protéinurie et l’albuminurie lorsque cela aide à caractériser l’atteinte. Une urine rouge avec bandelette positive mais sans hématies fait rechercher une hémoprotéine plutôt qu’affirmer une glomérulonéphrite. L’échographie explore notamment une obstruction lorsqu’une insuffisance rénale aiguë est présente.</p><p><b>Troisième étape : orienter la cause.</b> Reconstituer les délais infectieux, rechercher un foyer encore actif et les manifestations systémiques. Le complément, les anticorps et les cultures répondent à des hypothèses explicites. Une sérologie positive isolée peut être trompeuse : une endocardite peut s’accompagner d’ANCA. La biopsie se décide selon urgence, incertitude et influence attendue sur le traitement.</p><p><b>Quatrième étape : vérifier la trajectoire.</b> L’amélioration de la couleur des urines ne suffit pas. La diurèse, le poids, la pression, le potassium et la créatinine permettent de juger l’évolution immédiate ; les anomalies urinaires et le complément participent au suivi de la cause.</p>'''+key('Les examens de cause et les mesures de sécurité se conduisent en parallèle lorsque la fonction rénale se dégrade.'),('CH-ORIENTATION','CH-SEDIMENT','EU-IRA','INT-INFECTION'))
a+=sec(5,'5. Anamnèse analytique', '''<p>Faire préciser le début réel : première urine sombre, diminution de volume, gonflement palpébral au réveil, œdèmes déclives, prise de poids et essoufflement. Demander si la coloration intéresse toute la miction, s’il existe des caillots, des douleurs ou des brûlures. Une hématurie glomérulaire est classiquement totale et non caillotante ; ces caractères orientent mais ne remplacent pas l’analyse urinaire.</p>'''+table(['Question ciblée','Ce qu’elle cherche','Interprétation prudente'],[
['Infection ORL ou cutanée ? Date, traitement et guérison réelle ?','Intervalle libre compatible avec une forme postinfectieuse','Un délai d’environ deux semaines oriente ; il ne prouve ni le streptocoque ni la causalité.'],
['Hématurie contemporaine d’infections, épisodes antérieurs ?','Néphropathie à IgA possible','La récidive et la proximité temporelle renforcent l’hypothèse sans la confirmer.'],
['Fièvre persistante, frissons, plaie, infection articulaire, matériel implanté ?','Foyer infectieux toujours actif, notamment endocardite','Une infection peut être peu bruyante ; la recherche de foyer ne dépend pas d’une fièvre obligatoire.'],
['Purpura, douleurs articulaires ou abdominales, manifestations ORL, yeux rouges, hémoptysie ?','Maladie systémique ou atteinte réno-pulmonaire','Une atteinte extrarénale peut changer l’urgence et le bilan.'],
['Anciennes créatinines, protéinurie, hypertension, diabète ?','Atteinte aiguë sur maladie chronique et terrain vulnérable','Chercher les résultats antérieurs ; un chiffre isolé ne date pas la lésion.'],
['Maladie rénale ou surdité dans la famille ?','Atteinte héréditaire alternative','Une hématurie familiale n’est pas automatiquement bénigne.'],
['Médicaments, automédication, produits de contraste, anticoagulants ?','Néphrotoxicité, aggravation hémodynamique, autre lésion ou saignement','Un anticoagulant ne dispense jamais de rechercher la source de l’hématurie.']])+'''<p>Chez l’enfant, les parents aident à estimer les urines, les boissons et les changements de poids ; une baisse de diurèse peut être sous-estimée si elle n’est pas mesurée. Chez une personne âgée, le tableau peut être dominé par la dyspnée ou l’altération générale : conserver la recherche urinaire et les antécédents biologiques.</p>''',('CH-SEDIMENT','EU-HEMATURIA','EU-IGA','CH-URGENCE','INT-INFECTION'))
a+=sec(6,'6. Examen clinique : regarder au-delà des œdèmes', '''<p>Commencer par l’état général, la conscience, la respiration et la circulation. Mesurer la pression avec un brassard adapté et vérifier une valeur inattendue sans retarder la prise en charge d’un patient symptomatique. Chez l’enfant, l’interprétation tensionnelle dépend de l’âge, de la taille et du sexe ; un seuil adulte ne constitue pas une référence pédiatrique. Noter le poids actuel et rechercher un poids récent fiable.</p><p>Observer les paupières, les membres inférieurs et les régions déclives ; rechercher le godet et décrire sa distribution. L’examen respiratoire apprécie la fréquence, le travail respiratoire et les crépitants, avec la saturation. Une dyspnée peut correspondre à une surcharge, mais une hémorragie alvéolaire doit être envisagée devant une atteinte glomérulaire rapide, une anémie ou une hémoptysie. L’absence d’expectoration sanglante ne permet pas, à elle seule, d’éliminer cette dernière.</p><p>L’examen cardiovasculaire recherche les signes de congestion et un souffle pouvant orienter vers une endocardite. Examiner la peau et les articulations, ainsi que la sphère ORL selon les symptômes : porte d’entrée infectieuse, purpura, ulcération ou manifestations inflammatoires orientent des explorations différentes. Une absence de signes extrarénaux n’exclut pas une maladie limitée au rein.</p><p>Enfin, rechercher un globe vésical ou des éléments d’obstruction ; une insuffisance rénale avec urines peu abondantes ne prouve pas un défaut de filtration. L’examen doit aboutir à une description utilisable : état respiratoire et neurologique, pression, poids, volémie estimée, diurèse mesurée et signes orientant la cause. Il ne se réduit pas à « œdèmes présents ».</p>'''+key('La gravité se juge sur les organes menacés et la dynamique biologique, pas sur l’importance du gonflement visible.'),('CH-URGENCE','CH-SEDIMENT','EU-RPGN','EU-IRA'))
save('a',a)
b=sec(7,'7. Syndromes et classifications utiles', '''<p>Nommer le syndrome permet de hiérarchiser le bilan. Les catégories peuvent coexister ; elles ne doivent pas enfermer le raisonnement dans une cause unique.</p>'''+table(['Présentation','Éléments dominants','Ce qui la distingue'],[
['Néphritique aiguë','Hématurie glomérulaire, protéinurie, rétention hydrosodée et baisse variable de filtration','Installation rapide et recherche d’une inflammation glomérulaire.'],
['Néphrotique associée','Protéinurie importante et hypoalbuminémie','Ajoute des risques propres ; la présence d’hématurie ne l’exclut pas. Les seuils dépendent de l’âge et du référentiel.'],
['Rapidement progressive','Créatinine en forte ascension sur jours ou semaines','Urgence ; histologie et bilan immunologique orientent une thérapeutique spécifique.'],
['Réno-pulmonaire','Atteinte glomérulaire avec suspicion d’hémorragie alvéolaire','Menace vitale ; distinguer hémorragie et congestion sans retarder l’évaluation spécialisée.'],
['Hématurie isolée','Sans protéinurie significative, hypertension ni baisse de filtration','Autre rythme d’exploration si réellement stable ; ne pas y classer par erreur une atteinte aiguë.']])+'''<p>Il n’existe pas, dans les sources retenues, un score universel de gravité propre au syndrome néphritique aigu. On décrit donc séparément l’insuffisance rénale aiguë, les complications hydrosodées et les atteintes extrarénales. La classification histologique distingue activité, dépôts et cicatrices ; les sous-codes administratifs ne remplacent aucune de ces dimensions.</p>''',('EU-SYNDROMES','EU-RPGN','CH-SEDIMENT','CH-CIM'))
b+=sec(8,'8. Diagnostic positif : un faisceau cohérent', '''<p>Le diagnostic clinique repose sur une installation aiguë et des indices d’atteinte glomérulaire : hématurie confirmée, morphologie compatible ou cylindres, protéinurie et retentissement rénal ou hydrosodé. La bandelette seule n’identifie ni la cellule ni la localisation. Les critères morphologiques HUG — notamment plus de 5 % d’acanthocytes ou des cylindres hématiques — sont des repères de laboratoire ; leur sensibilité limitée interdit de conclure à l’absence de maladie sur un résultat négatif.</p><p>La fonction rénale doit être comparée à une valeur antérieure et suivie. Dans la vignette, le passage de 75 à 150 µmol/L correspond à un doublement : 150 ÷ 75 = 2. Ce calcul décrit une dynamique importante, même si le chiffre final paraît moins impressionnant que celui d’une insuffisance chronique avancée. Les équations de débit estimé ne donnent pas une mesure fiable de la filtration instantanée lorsque la créatinine change rapidement.</p><p>La cause postinfectieuse reste une hypothèse jusqu’à la confrontation des éléments : infection préalable crédible, délai, complément, recherche d’infection persistante et évolution. Un résultat d’anticorps antistreptococciques témoigne d’une réponse immunologique ; il ne constitue pas à lui seul une preuve que toute lésion rénale est poststreptococcique. Les sérologies, cultures et la biopsie répondent à des questions différentes.</p><p>La biopsie apporte la classification histologique quand son résultat est nécessaire à la décision. Elle est particulièrement importante en cas de progression rapide, de présentation atypique ou de doute causal. Elle n’est pas présentée comme obligatoire pour chaque enfant avec une forme postinfectieuse typique favorable ; la décision relève du néphrologue.</p>'''+trap('Attendre une hématurie macroscopique, tous les signes classiques ou une sérologie positive peut retarder le diagnostic.'),('CH-SEDIMENT','EU-IRA','EU-POSTINF','INT-GN-GENERAL','INT-INFECTION'))
b+=sec(9,'9. Explorations : une question par examen', '''<p>Le bilan initial mesure la gravité et confirme la localisation : créatinine, électrolytes dont potassium, analyse d’urines avec sédiment et quantification protéique ; numération et évaluation acido-basique selon le tableau. L’électrocardiogramme recherche le retentissement d’une hyperkaliémie. L’échographie évalue notamment les voies excrétrices et participe à la préparation d’une éventuelle biopsie. Un examen normal n’efface pas une atteinte glomérulaire.</p><p>Le bilan causal est orienté : C3/C4, anticorps antinucléaires et anti-ADN, ANCA anti-MPO/anti-PR3, anticorps anti-membrane basale, cryoglobulines et sérologies infectieuses selon les indices. Si une infection active ou une endocardite est plausible, les hémocultures et l’évaluation du foyer prennent une place essentielle. Les prélèvements microbiologiques se coordonnent avec l’antibiothérapie et l’urgence clinique.</p><p>L’onglet Examens détaille le prélèvement, ce que chaque test permet de conclure, ses limites et la façon de relier les résultats. Le but est une réponse utile à la décision, sans multiplier des examens dont l’interprétation resterait sans contexte.</p>''',('CH-SEDIMENT','EU-IRA','EU-POSTINF','INT-INFECTION','EU-RPGN'))
b+=sec(10,'10. Arbre diagnostique et diagnostics différentiels', '''<ol><li><b>Atteinte d’organe menaçante ?</b> Dyspnée sévère, trouble neurologique, hyperkaliémie, anurie ou aggravation rapide imposent l’évaluation hospitalière immédiate. Poursuivre l’enquête pendant la stabilisation.</li><li><b>Hématies réellement présentes ?</b> Confirmer par sédiment. Si bandelette positive sans hématies, explorer hémoglobinurie ou myoglobinurie selon la clinique ; si bandelette négative, considérer notamment pigments alimentaires ou médicamenteux.</li><li><b>Origine glomérulaire ?</b> Morphologie, cylindres, protéinurie et fonction orientent. Caillots, douleur ou symptômes mictionnels font aussi rechercher une cause urologique ; une association reste possible.</li><li><b>Infection active ou antécédent récent ?</b> Rechercher un foyer et documenter la chronologie. Une hématurie synchrone d’une infection ORL évoque aussi l’IgA ; un intervalle libre évoque une forme postinfectieuse.</li><li><b>Complément, atteintes systémiques et vitesse d’évolution ?</b> Un C3 bas oriente vers certaines causes à complexes immuns ou du complément ; un complément normal n’exclut pas IgA, vascularite ou maladie anti-membrane basale. Croiser avec les tests ciblés et décider de la biopsie.</li></ol>'''+table(['Alternative','Éléments qui la font rechercher','Ce qui empêche une conclusion trop rapide'],[
['Infection urinaire ou lithiase','Dysurie, douleur, culture, imagerie','Une leucocyturie peut aussi accompagner une inflammation glomérulaire.'],
['Obstacle urinaire','Globe, dilatation, anurie ou rétention','La diurèse basse n’est pas synonyme de glomérulonéphrite.'],
['Néphrite interstitielle ou atteinte tubulaire','Exposition médicamenteuse, contexte infectieux ou hémodynamique, sédiment différent','Les profils peuvent se chevaucher ; la biopsie peut être nécessaire.'],
['Maladie héréditaire de la membrane basale','Hématurie ancienne ou familiale, surdité','Une histoire familiale ne prouve pas une évolution bénigne.'],
['Glomérulopathie chronique décompensée','Anomalies anciennes, hypertension ou maladie rénale préalable','La composante aiguë doit être traitée ; le dossier antérieur aide à la distinguer.'],
['Maladie systémique ou infection imitant une vascularite','Purpura, signes pulmonaires, infection persistante, sérologies','Des ANCA peuvent être présents dans une endocardite ; ne pas traiter un résultat isolé.']])+key('Le complément trie des hypothèses ; il ne remplace ni la clinique, ni la microbiologie, ni l’histologie.'),('CH-SEDIMENT','EU-HEMATURIA','EU-IRA','EU-RPGN','INT-INFECTION'))
b+=sec(11,'11. Prise en charge suisse : soutenir puis traiter la cause', '''<h3>Stabiliser et organiser le niveau de soins</h3><p>Une forme avec atteinte respiratoire ou neurologique, hyperkaliémie, anurie ou aggravation rapide nécessite un milieu hospitalier capable d’assurer surveillance, néphrologie et épuration si nécessaire. Mesurer les entrées/sorties, le poids, la pression et les paramètres biologiques selon la gravité. Revoir les médicaments et les apports, notamment sodium, potassium et substances potentiellement néphrotoxiques. Une surcharge ne se traite pas par un remplissage liquidien automatique.</p><h3>Corriger la surcharge avec une surveillance rapprochée</h3><p>Le diurétique de l’anse peut être utilisé lorsque la surcharge et la fonction résiduelle le justifient. Il ne guérit pas l’inflammation et ne prouve pas, par l’augmentation des urines, que la filtration a récupéré. Le choix de voie et de dose dépend de l’urgence, de l’absorption, de la réponse et des contre-indications. Les FI suisses exactes de Lasix sont détaillées dans Pharmacologie, y compris les différences enfant/adulte et la contre-indication d’anurie mentionnée par le produit.</p><p>Les apports hydriques et sodés sont ajustés à la diurèse, aux pertes et à l’état circulatoire. Une restriction excessive peut aussi être délétère ; aucun volume fixe n’est imposé à tous les patients. Le potassium se décide sur les résultats : un conseil générique de régime riche en potassium ne s’applique pas à une insuffisance rénale aiguë hyperkaliémique.</p><h3>Contrôler la pression sans confondre traitement de fond et urgence</h3><p>Une pression élevée avec atteinte aiguë d’organe relève d’une prise en charge surveillée et individualisée. L’amlodipine orale est une option de traitement de fond de l’adulte selon sa FI ; elle ne remplace pas le traitement d’une urgence hypertensive. La réduction de protéinurie par blocage du système rénine-angiotensine peut avoir une place après stabilisation dans certaines maladies, mais ne constitue pas un réflexe dans l’oligurie avec créatinine ascendante ou hyperkaliémie.</p><h3>Traiter la cause réellement établie</h3><p>Dans la forme postinfectieuse typique, la prise en charge rénale est surtout symptomatique. Une infection active doit être traitée selon son foyer et la microbiologie ; une endocardite nécessite un schéma propre et ne se traite pas par le simple protocole oral d’une angine. Une antibiothérapie donnée pour éradiquer un streptocoque encore présent vise aussi à limiter la transmission ; elle n’a pas démontré qu’elle renverse le cours d’une glomérulonéphrite déjà installée.</p><p>Les corticoïdes ne sont pas un traitement systématique de toute glomérulonéphrite postinfectieuse. Une forme à croissants ou une détérioration sévère exige une décision spécialisée fondée sur la cause, l’activité histologique, les risques infectieux et les preuves disponibles. Les vascularites et maladies anti-membrane basale ont des traitements spécifiques urgents ; aucun protocole unique d’immunosuppression n’est déduit du seul intitulé N00.</p><p>Une hyperkaliémie menaçante, une acidose sévère ou une surcharge pulmonaire réfractaire peuvent imposer une épuration extrarénale. La décision repose sur le contexte et les complications, pas sur un seuil isolé de créatinine. Les mesures de stabilisation et l’organisation de l’épuration ne doivent pas attendre la fin du bilan étiologique.</p>'''+key('Traiter une infection et traiter une inflammation auto-immune ne sont pas des décisions interchangeables ; sécuriser le patient pendant que la cause est précisée.'),('CH-ORIENTATION','EU-IRA','EU-POSTINF','INT-INFECTION','FI-LASIX-IV','FI-LASIX-PO','FI-NORVASC'))
b+=sec(12,'12. Prévention, suivi et pronostic', '''<p>Le suivi immédiat repose sur la trajectoire : respiration, pression, poids, diurèse, créatinine et électrolytes. Une amélioration clinique doit s’accompagner d’une vérification biologique ; inversement, une hématurie résiduelle n’indique pas à elle seule une aggravation si les autres paramètres évoluent favorablement. La fréquence des contrôles dépend de la sévérité initiale et de la stabilité ; elle n’est pas remplacée par un calendrier identique pour tous.</p><p>Après la phase aiguë, suivre les anomalies urinaires, la protéinurie, la fonction et le complément lorsqu’il était abaissé. KDIGO indique qu’un C3 encore bas au-delà de douze semaines peut motiver une biopsie pour rechercher notamment une glomérulopathie à C3. Ce repère n’autorise pas à attendre trois mois devant une créatinine ascendante, une protéinurie persistante importante ou une autre présentation atypique.</p><p>Le pronostic de la forme poststreptococcique typique de l’enfant est généralement favorable. Chez l’adulte âgé, diabétique ou porteur d’une infection active, la récupération peut être incomplète et la maladie rénale chronique persister. La biopsie renseigne l’activité et les cicatrices, mais son interprétation s’intègre à l’état clinique et aux comorbidités.</p><p>La prévention vise les infections et les expositions évitables, le traitement adapté des foyers identifiés, le bon usage des médicaments et la poursuite du suivi si pression, protéinurie ou fonction restent anormales. L’information au patient doit inclure les motifs de retour urgent : baisse nette des urines, essoufflement, aggravation rapide des œdèmes, symptômes neurologiques ou dégradation de l’état général.</p><h3>Situations particulières</h3><p><b>Enfant :</b> interpréter pression et fonction selon l’âge ; utiliser un recueil urinaire réalisable et distinguer les posologies pédiatriques des protocoles adultes. <b>Personne âgée ou diabétique :</b> rechercher une infection active parfois peu manifeste et une maladie rénale antérieure. <b>Grossesse :</b> toute hypertension avec atteinte rénale nouvelle justifie une évaluation obstétricale et néphrologique ; ne pas attribuer automatiquement le tableau à une infection récente ni transposer une prescription adulte sans vérification de grossesse. <b>Maladie chronique préalable :</b> documenter le niveau antérieur et maintenir le suivi après résolution de l’épisode aigu.</p>''',('INT-INFECTION','CH-ORIENTATION','INT-GN-GENERAL','FI-LASIX-IV','FI-NORVASC'))
b+=sec(13,'13. Points clés et entraînement fédéral', '''<ol><li>Une urine sombre n’est pas encore une hématurie glomérulaire : confirmer et localiser.</li><li>Le syndrome néphritique est clinique ; la cause peut être infectieuse, immunologique ou différente du premier scénario évoqué.</li><li>La vitesse de variation de créatinine et la diurèse comptent autant que le chiffre isolé.</li><li>Rechercher sans délai surcharge pulmonaire, hyperkaliémie, atteinte neurologique et syndrome réno-pulmonaire.</li><li>Le complément et les anticorps orientent ; aucun résultat isolé ne remplace la confrontation clinique.</li><li>Les diurétiques soulagent la surcharge, les antibiotiques traitent une infection, et l’immunosuppression répond à une indication spécifique.</li><li>La récupération se vérifie par un suivi clinique et biologique, particulièrement si le tableau s’écarte d’une forme typique favorable.</li></ol><p id="n00-federal">La correspondance pédagogique avec <b>PROFILES 2017</b> porte sur les situations SSP 63 (anomalies de diurèse), SSP 64 (notamment hématurie), SSP 161 (marqueurs de fonction rénale), SSP 164 (sédiment anormal) et SSP 173 (protéinurie). Les exigences MEBEKO de l’examen 2026 associent connaissances et compétences cliniques dans un blueprint multidimensionnel. Les exercices ci-dessous sont des créations pédagogiques MEDINA, sans statut de question officielle ni correspondance CIM validée par la commission.</p><p><button class="w" data-k="n00-cas-1">Cas 1 — Quelle priorité devant une dyspnée et des urines sombres ?</button></p><p><button class="w" data-k="n00-cas-2">Cas 2 — ANCA positifs et fièvre persistante : quelle précaution ?</button></p><p><button class="w" data-k="n00-cas-3">Cas 3 — Le C3 reste bas : attendre ou réévaluer ?</button></p><p><button class="w" data-k="n00-cas-4">Cas 4 — Calculer une diurèse pondérale et un rapport urinaire</button></p>''',('CH-PROFILES','CH-MEBEKO','CH-URGENCE','INT-INFECTION','EU-IRA'))
b+=sec(14,'14. Pièges à éviter', table(['Erreur','Pourquoi elle trompe','Correction du raisonnement'],[
['Assimiler toute forme aiguë à une GN poststreptococcique','Le même syndrome a plusieurs causes','Vérifier chronologie, foyer actif, immunologie et évolution.'],
['Exclure sur absence de cylindre ou d’œdème','Sensibilité imparfaite et présentation incomplète','Croiser sédiment, protéines, fonction et clinique.'],
['Lire un débit estimé comme une mesure instantanée en phase aiguë','La créatinine n’est pas à l’état stationnaire','Suivre créatinine et diurèse dans le temps.'],
['Interpréter ANCA positifs comme preuve suffisante de vascularite','Une endocardite peut aussi donner des ANCA','Rechercher l’infection si le contexte l’évoque.'],
['Donner corticoïdes pour toute inflammation glomérulaire','Une infection active peut être aggravée ; bénéfice non établi dans la forme postinfectieuse courante','Fonder l’indication sur la cause et l’évaluation spécialisée.'],
['Confondre reprise de diurèse sous furosémide et guérison','Le traitement modifie l’excrétion sans réparer directement le filtre','Suivre aussi fonction, pression, poids et électrolytes.'],
['Remplacer une urgence par un traitement de fond oral','Une atteinte aiguë d’organe exige un environnement surveillé','Orienter immédiatement au niveau de soins adapté.'],
['Utiliser un suffixe histologique sans preuve','Les sous-codes morphologiques ne sont pas des hypothèses','Conserver la distinction syndrome, cause et lésion documentée.']])+key('Une hypothèse cohérente reste une hypothèse tant que ses éléments discriminants ne sont pas vérifiés.'),('CH-SEDIMENT','EU-IRA','INT-INFECTION','CH-CIM'))
b+=sec('annexe-cim','Annexe — Classer après le diagnostic clinique', '''<p>Dans la CIM-10-GM 2024 française diffusée par l’OFS, N00 est le syndrome néphritique aigu. La catégorie exclut notamment la néphrite tubulo-interstitielle aiguë (N10) et le syndrome néphritique sans précision (N05.-). Les subdivisions communes N00–N07 décrivent la morphologie ; .0 à .8 supposent normalement une identification précise par biopsie ou autopsie. Elles ne désignent pas dix maladies aiguës ayant chacune un traitement autonome.</p>'''+table(['Code','Modification morphologique','Lecture clinique'],[
['N00.0','Anomalies glomérulaires mineures','Libellé morphologique ; ne pas déduire un syndrome néphrotique de ce seul suffixe.'],
['N00.1','Lésions glomérulaires segmentaires et focales','Localisation de la lésion, pas preuve d’une cause.'],
['N00.2','Glomérulonéphrite membraneuse diffuse','Morphologie à confronter au syndrome et au compte rendu.'],
['N00.3','Glomérulonéphrite mésangio-proliférative diffuse','Une prolifération mésangiale n’identifie pas à elle seule l’IgA.'],
['N00.4','Glomérulonéphrite proliférative endocapillaire diffuse','Compatible avec plusieurs causes, dont certaines infectieuses.'],
['N00.5','Glomérulonéphrite mésangiocapillaire diffuse','Profil membranoprolifératif à explorer étiologiquement.'],
['N00.6','Maladie à dépôt dense','Caractérisation spécialisée, non déduite d’un C3 bas isolé.'],
['N00.7','Glomérulonéphrite diffuse en croissant','Lésion extracapillaire ; évaluer la cause et la rapidité clinique.'],
['N00.8','Autres modifications morphologiques','Nécessite une description histologique appropriée.'],
['N00.9','Type de modification morphologique non précisé','Ne transforme pas une hypothèse en preuve histologique.']])+'''<p>Le bloc autorise, selon le dossier, des codes supplémentaires pour certaines atteintes hypertensives, une maladie chronique ou une insuffisance rénale aiguë. Le choix final de codage suit la documentation et les règles applicables ; il ne pilote pas à lui seul le traitement.</p>''',('CH-CIM','EU-HISTO'))
b+='</div></div>'
save('b',b)
print('N00 a/b : plan clinique 14 points rédigé, relecture encore requise.')
